class User(BaseModel):
    email: str

    @field_validator('email')
    @classmethod
    def validate_email(cls, v):
        if '@' not in v:
            raise ValueError('email must contain @')
        return v

# Test the model
if __name__ == '__main__':
    # Valid email
    user = User(email='andrea.za94@gmail.com')
